import { LogicWrapper, MakeLogicType, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import * as api from '../../generated/api'
import type { AccountApi } from '../../generated/api.schemas'
import { accountPropertyUpdatesLogic } from './accountPropertyUpdatesLogic'
import type { AccountSidebarPropertyData } from './accountSidebarProperties'

export interface AccountPropertyDataLogicProps {
    projectId: number
    accountId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountPropertyDataLogicValues {
    account: AccountApi | null
    accountLoadFailed: boolean
    accountLoading: boolean
    propertyData: AccountSidebarPropertyData | null
    propertyDataLoadFailed: boolean
    propertyDataLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountPropertyDataLogicActions {
    loadAccount: (_: void) => void
    loadAccountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAccountSuccess: (
        account: AccountApi,
        payload?: void
    ) => {
        account: AccountApi
        payload?: void
    }
    loadPropertyData: (_: void) => void
    loadPropertyDataFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPropertyDataSuccess: (
        propertyData: AccountSidebarPropertyData,
        payload?: void
    ) => {
        propertyData: AccountSidebarPropertyData
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountPropertyDataLogicMeta {
    key: string
}

export type accountPropertyDataLogicType = MakeLogicType<
    accountPropertyDataLogicValues,
    accountPropertyDataLogicActions,
    AccountPropertyDataLogicProps,
    accountPropertyDataLogicMeta
>

export const accountPropertyDataLogic: LogicWrapper<accountPropertyDataLogicType> = kea<accountPropertyDataLogicType>([
    props({} as AccountPropertyDataLogicProps),
    key(({ projectId, accountId }) => `${projectId}:${accountId}`),
    path((key) => ['products', 'customer_analytics', 'accountPropertyDataLogic', key]),
    connect(() => ({ logic: [accountPropertyUpdatesLogic] })),
    loaders(({ props, cache, values }) => ({
        propertyData: [
            null as AccountSidebarPropertyData | null,
            {
                loadPropertyData: async (_: void, breakpoint): Promise<AccountSidebarPropertyData> => {
                    const [customValues, relationships] = await Promise.all([
                        api.accountsCustomPropertyValuesList(String(props.projectId), props.accountId),
                        api.accountsRelationshipsList(String(props.projectId), props.accountId),
                    ])
                    breakpoint()
                    return { customValues, relationships }
                },
            },
        ],
        account: [
            null as AccountApi | null,
            {
                loadAccount: async (_: void, breakpoint): Promise<AccountApi> => {
                    const revision = cache.accountRevision ?? 0
                    const account = await api.accountsRetrieve(String(props.projectId), props.accountId)
                    breakpoint()
                    return revision !== (cache.accountRevision ?? 0) ? (values.account ?? account) : account
                },
            },
        ],
    })),
    reducers({
        propertyDataLoadFailed: [
            false,
            {
                loadPropertyData: () => false,
                loadPropertyDataSuccess: () => false,
                loadPropertyDataFailure: () => true,
            },
        ],
        accountLoadFailed: [
            false,
            { loadAccount: () => false, loadAccountSuccess: () => false, loadAccountFailure: () => true },
        ],
    }),
    listeners(({ actions, props, cache }) => ({
        [accountPropertyUpdatesLogic.actionTypes.accountUpdated]: ({ projectId, account }) => {
            if (projectId === props.projectId && account.id === props.accountId) {
                cache.accountRevision = (cache.accountRevision ?? 0) + 1
                actions.loadAccountSuccess(account)
            }
        },
    })),
])
